<?php
declare(strict_types=1);
require_once __DIR__.'/app/bootstrap.php';
$ctx=growth_seller_context();$uid=(int)$ctx['owner_id'];$msg='';$err='';
try{if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$a=(string)($_POST['action']??'');if($a==='ad'){if(!setting_bool('self_service_ads_enabled',true))throw new RuntimeException('Self-service ads are disabled.');$businessId=(int)($_POST['business_id']??0);$owned=(int)v41_scalar("SELECT COUNT(*) FROM businesses WHERE id=? AND owner_id=?",[$businessId,$uid]);if(!$owned)throw new RuntimeException('Choose one of your businesses.');v41_create_ad(['business_id'=>$businessId,'title'=>trim((string)$_POST['title']),'placement'=>trim((string)$_POST['placement']),'city_id'=>(int)($_POST['city_id']??0),'category_id'=>0,'target_url'=>trim((string)$_POST['target_url']),'image_url'=>trim((string)$_POST['image_url']),'daily_budget'=>(float)($_POST['daily_budget']??0),'total_budget'=>(float)($_POST['total_budget']??0),'starts_at'=>!empty($_POST['starts_at'])?str_replace('T',' ',$_POST['starts_at']).':00':null,'ends_at'=>!empty($_POST['ends_at'])?str_replace('T',' ',$_POST['ends_at']).':00':null,'status'=>'pending'],$uid);$msg='Ad campaign submitted for approval.';}elseif($a==='boost'){if(!setting_bool('listing_boosts_enabled',true))throw new RuntimeException('Listing boosts are disabled.');$type=(string)($_POST['entity_type']??'business');$eid=(int)($_POST['entity_id']??0);$ok=false;if($type==='business')$ok=(bool)v41_scalar("SELECT COUNT(*) FROM businesses WHERE id=? AND owner_id=?",[$eid,$uid]);elseif($type==='product')$ok=(bool)v41_scalar("SELECT COUNT(*) FROM store_products WHERE id=? AND seller_user_id=?",[$eid,$uid]);if(!$ok)throw new RuntimeException('You can only boost your own business/product.');v41_create_boost(['entity_type'=>$type,'entity_id'=>$eid,'boost_type'=>(string)($_POST['boost_type']??'featured'),'amount'=>(float)($_POST['amount']??0),'starts_at'=>date('Y-m-d H:i:s'),'ends_at'=>date('Y-m-d H:i:s',time()+max(1,(int)($_POST['days']??7))*86400),'status'=>'pending'],$uid);$msg='Boost request submitted.';}}}catch(Throwable $e){$err=$e->getMessage();}
$biz=v41_rows("SELECT id,name,city_id FROM businesses WHERE owner_id=? ORDER BY name",[$uid]);$products=v41_rows("SELECT id,title FROM store_products WHERE seller_user_id=? ORDER BY id DESC LIMIT 200",[$uid]);$ads=v41_rows("SELECT * FROM self_service_ad_campaigns WHERE user_id=? ORDER BY id DESC LIMIT 100",[$uid]);$boosts=v41_rows("SELECT * FROM listing_boosts WHERE user_id=? ORDER BY id DESC LIMIT 100",[$uid]);
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Seller Advertising - <?=e(setting('site_name','ShahkotPK'))?></title><style>body{font-family:Arial,sans-serif;background:#f6f8fb;color:#172033;margin:0}.wrap{max-width:1200px;margin:auto;padding:24px}.hero{background:linear-gradient(135deg,#081b2a,#0f7058);color:#fff;padding:28px;border-radius:24px}.hero a{color:#fff}.grid{display:grid;grid-template-columns:1fr 1fr;gap:18px;margin-top:18px}.card{background:#fff;border:1px solid #e3e9f0;border-radius:18px;padding:20px}.form{display:grid;gap:10px}.form input,.form select{padding:10px;border:1px solid #cad5e2;border-radius:10px}.btn{padding:10px 13px;border:0;border-radius:10px;background:#0f7058;color:#fff;font-weight:800}.msg{padding:12px;border-radius:10px;margin-top:12px;background:#ecfdf5}.err{background:#fff1f2}.table{overflow:auto}.table table{width:100%;min-width:650px;border-collapse:collapse}.table th,.table td{padding:9px;border-bottom:1px solid #eef2f6;text-align:left}@media(max-width:850px){.grid{grid-template-columns:1fr}}</style></head><body><div class="wrap"><div class="hero"><small>SELLER GROWTH v4.1</small><h1>Advertising & Listing Boosts</h1><p>Create campaigns for your own business and request paid boosts without asking Admin to build the listing manually.</p><a href="/seller-growth-dashboard.php">← Seller Growth Dashboard</a></div><?php if($msg):?><div class="msg"><?=e($msg)?></div><?php endif;?><?php if($err):?><div class="msg err"><?=e($err)?></div><?php endif;?><div class="grid"><div class="card"><h2>Create Ad Campaign</h2><form method="post" class="form"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="ad"><select name="business_id" required><?php foreach($biz as $b):?><option value="<?=$b['id']?>"><?=e($b['name'])?></option><?php endforeach;?></select><input name="title" placeholder="Campaign title" required><select name="placement"><option>homepage</option><option>shop</option><option>search</option><option>category</option><option>property</option></select><input name="target_url" placeholder="Target URL"><input name="image_url" placeholder="Ad image URL"><input type="number" step="0.01" name="daily_budget" placeholder="Daily budget"><input type="number" step="0.01" name="total_budget" placeholder="Total budget"><label>Start<input type="datetime-local" name="starts_at"></label><label>End<input type="datetime-local" name="ends_at"></label><button class="btn">Submit Campaign</button></form></div><div class="card"><h2>Boost a Listing</h2><form method="post" class="form"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="boost"><select name="entity_type" id="boostType"><option value="business">Business</option><option value="product">Product</option></select><select name="entity_id" required><optgroup label="Businesses"><?php foreach($biz as $b):?><option value="<?=$b['id']?>"><?=e($b['name'])?></option><?php endforeach;?></optgroup><optgroup label="Products"><?php foreach($products as $p):?><option value="<?=$p['id']?>"><?=e($p['title'])?></option><?php endforeach;?></optgroup></select><select name="boost_type"><option>featured</option><option>top</option><option>highlight</option><option>homepage</option></select><input type="number" name="days" value="7" min="1" max="90"><input type="number" step="0.01" name="amount" placeholder="Quoted amount"><button class="btn">Request Boost</button></form></div></div><div class="grid"><div class="card table"><h2>My Campaigns</h2><table><tr><th>Campaign</th><th>Budget</th><th>Performance</th><th>Status</th></tr><?php foreach($ads as $r):?><tr><td><?=e($r['title'])?></td><td><?=e(v41_money($r['total_budget']))?></td><td><?=number_format((int)$r['impressions'])?> / <?=number_format((int)$r['clicks'])?></td><td><?=e($r['status'])?></td></tr><?php endforeach;?></table></div><div class="card table"><h2>My Boosts</h2><table><tr><th>Listing</th><th>Type</th><th>Ends</th><th>Status</th></tr><?php foreach($boosts as $r):?><tr><td><?=e($r['entity_type'])?> #<?=$r['entity_id']?></td><td><?=e($r['boost_type'])?></td><td><?=e($r['ends_at'])?></td><td><?=e($r['status'])?></td></tr><?php endforeach;?></table></div></div></div></body></html>
